from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
from pathlib import Path
from datetime import datetime, date

INPUT = '/root/data/workbook.xlsx'
OUTPUT = '/root/output/result.xlsx'
Path('/root/output').mkdir(parents=True, exist_ok=True)


def norm(v):
    if v is None:
        return None
    if isinstance(v, (datetime, date)):
        return v.year
    if isinstance(v, float) and v.is_integer():
        return int(v)
    if isinstance(v, str):
        s = v.strip()
        if s == '':
            return None
        try:
            f = float(s)
            return int(f) if f.is_integer() else f
        except ValueError:
            return s
    return v


def fmt(v):
    if v is None:
        return ''
    return str(v)


def print_task(task):
    cols = [4, 8, 9, 10, 11, 12]
    labels = [get_column_letter(c) for c in cols]
    print('Task sheet rows 10-50, columns D,H-L (before writing formulas):')
    print('Row\t' + '\t'.join(labels))
    for r in range(10, 51):
        vals = [fmt(task.cell(r, c).value) for c in cols]
        print(str(r) + '\t' + '\t'.join(vals))
    print()


def print_data(data):
    min_col = None
    max_col = None
    for row in data.iter_rows(min_row=20, max_row=39):
        for cell in row:
            if cell.value is not None:
                min_col = cell.column if min_col is None else min(min_col, cell.column)
                max_col = cell.column if max_col is None else max(max_col, cell.column)
    if min_col is None:
        min_col, max_col = 1, 1
    labels = [get_column_letter(c) for c in range(min_col, max_col + 1)]
    print('Data sheet rows 20-39, all used columns in that block (before writing formulas):')
    print('Row\t' + '\t'.join(labels))
    for r in range(20, 40):
        vals = [fmt(data.cell(r, c).value) for c in range(min_col, max_col + 1)]
        print(str(r) + '\t' + '\t'.join(vals))
    print()
    return min_col, max_col


def cell_range(sheet_name, start_col, start_row, end_col, end_row):
    return f"{sheet_name}!${get_column_letter(start_col)}${start_row}:${get_column_letter(end_col)}${end_row}"


def main():
    wb = load_workbook(INPUT)
    task = wb['Task']
    data = wb['Data']

    print_task(task)
    block_min_col, block_max_col = print_data(data)

    # Identify series-code column in Data rows 21-38 by matching the series codes listed in Task col D.
    task_code_rows = list(range(12, 18)) + list(range(19, 25)) + list(range(26, 32))
    task_codes = {norm(task.cell(r, 4).value) for r in task_code_rows if task.cell(r, 4).value is not None}
    best_col, best_count = None, -1
    for c in range(block_min_col, block_max_col + 1):
        vals = [norm(data.cell(r, c).value) for r in range(21, 39)]
        count = sum(1 for v in vals if v in task_codes)
        if count > best_count:
            best_col, best_count = c, count
    if best_col is None or best_count == 0:
        raise RuntimeError('Could not identify Data sheet series-code column from rows 21-38.')

    # Identify Data row-20 year header columns by matching Task years in H10:L10.
    task_years = [norm(task.cell(10, c).value) for c in range(8, 13)]
    header_cols_matching_task = [c for c in range(block_min_col, block_max_col + 1)
                                 if norm(data.cell(20, c).value) in task_years]
    if not header_cols_matching_task:
        raise RuntimeError('Could not identify any Data sheet year headers in row 20 matching Task H10:L10.')

    # Use the exact contiguous row-20 header span containing all non-empty year headers, excluding the series-code column.
    # This preserves the intended INDEX/MATCH pattern (e.g. Data!$B$20:$S$20) while adapting to the observed workbook.
    year_header_cols = []
    for c in range(block_min_col, block_max_col + 1):
        if c == best_col:
            continue
        v = norm(data.cell(20, c).value)
        if isinstance(v, int) or isinstance(v, float):
            year_header_cols.append(c)
    if not year_header_cols:
        # Fallback: contiguous span covering just the matching task year columns.
        year_header_cols = header_cols_matching_task
    data_start_col, data_end_col = min(year_header_cols), max(year_header_cols)

    series_range = cell_range('Data', best_col, 21, best_col, 38)
    values_range = cell_range('Data', data_start_col, 21, data_end_col, 38)
    headers_range = cell_range('Data', data_start_col, 20, data_end_col, 20)

    print('Observed lookup ranges:')
    print(f"  Series codes: {series_range}")
    print(f"  Data values:  {values_range}")
    print(f"  Year headers: {headers_range}")
    print()

    # Step 1 lookup formulas.
    lookup_rows = list(range(12, 18)) + list(range(19, 25)) + list(range(26, 32))
    for r in lookup_rows:
        for c in range(8, 13):
            col = get_column_letter(c)
            task.cell(r, c).value = f"=INDEX({values_range},MATCH($D{r},{series_range},0),MATCH({col}$10,{headers_range},0))"

    # Step 2 net capacity headroom formulas.
    for r in range(35, 41):
        for c in range(8, 13):
            col = get_column_letter(c)
            task.cell(r, c).value = f"=({col}{r-23}-{col}{r-16})/{col}{r-9}*100"

    # Step 3 statistics. Determine mapping from actual labels, with a conservative fallback to the instructed order.
    label_text = {}
    for r in range(42, 48):
        parts = []
        for c in range(4, 8):  # D/E/F/G labels noted in the instruction.
            v = task.cell(r, c).value
            if v is not None:
                parts.append(str(v).strip().lower())
        label_text[r] = ' '.join(parts)

    def formula_for_label(label, col):
        rng = f"{col}35:{col}40"
        l = label.lower()
        if 'min' in l and 'admin' not in l:
            return f"=MIN({rng})"
        if 'max' in l:
            return f"=MAX({rng})"
        if 'median' in l:
            return f"=MEDIAN({rng})"
        if 'mean' in l or 'average' in l:
            return f"=AVERAGE({rng})"
        if '25' in l or '0.25' in l or '1st quartile' in l or 'first quartile' in l or 'q1' in l:
            return f"=PERCENTILE({rng},0.25)"
        if '75' in l or '0.75' in l or '3rd quartile' in l or 'third quartile' in l or 'q3' in l:
            return f"=PERCENTILE({rng},0.75)"
        return None

    fallback = {
        42: lambda col: f"=MIN({col}35:{col}40)",
        43: lambda col: f"=MAX({col}35:{col}40)",
        44: lambda col: f"=MEDIAN({col}35:{col}40)",
        45: lambda col: f"=AVERAGE({col}35:{col}40)",
        46: lambda col: f"=PERCENTILE({col}35:{col}40,0.25)",
        47: lambda col: f"=PERCENTILE({col}35:{col}40,0.75)",
    }
    print('Statistic row labels observed in Task columns D:G:')
    for r in range(42, 48):
        print(f"  Row {r}: {label_text[r]}")
    print()

    for r in range(42, 48):
        for c in range(8, 13):
            col = get_column_letter(c)
            formula = formula_for_label(label_text[r], col)
            if formula is None:
                formula = fallback[r](col)
            task.cell(r, c).value = formula

    # Step 4 weighted mean.
    for c in range(8, 13):
        col = get_column_letter(c)
        task.cell(50, c).value = f"=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)"

    wb.save(OUTPUT)
    print(f'Saved workbook to {OUTPUT}')
    print()

    # Re-open and print all modified formulas.
    check_wb = load_workbook(OUTPUT, data_only=False)
    check_task = check_wb['Task']
    modified_rows = lookup_rows + list(range(35, 41)) + list(range(42, 48)) + [50]
    print('Formulas in modified cells after re-opening saved workbook:')
    for r in modified_rows:
        vals = [f"{get_column_letter(c)}{r}={check_task.cell(r, c).value}" for c in range(8, 13)]
        print('; '.join(vals))

    percentile_bad = []
    for r in (46, 47):
        for c in range(8, 13):
            v = check_task.cell(r, c).value
            if v is None or 'PERCENTILE(' not in v or 'PERCENTILE.' in v:
                percentile_bad.append(f"{get_column_letter(c)}{r}:{v}")
    if percentile_bad:
        raise RuntimeError('Percentile formula verification failed: ' + ', '.join(percentile_bad))
    print()
    print('Verified rows 46-47 use PERCENTILE with no dot suffix.')


if __name__ == '__main__':
    main()

